Suppose the total iteration rounds of alg1 is $T$. Under 2 and 3, if $k_2$ in 9 exists within $T$ iterations, we have:
\begin{align}
\bar{m}^y_{t+1} \leq 
\begin{cases} 
C_{m^y}, & t < k_2, \\
C_{m^y}+c_0+d_0 \sum_{k=\min\{k_1,k_2\}}^t \frac{\|\bar{\nabla} F(\mathbf{x}_k,\mathbf{y}_k,\mathbf{v}_k)\|^2}{[\bar{m}^x_{k+1}]^2\max \big\{\bar{m}^v_{k+1}, \bar{m}^y_{k+1}\big\}}, 
& t \geq k_2.
\end{cases}
\end{align}
where $c_0, d_0$ are defined as:
\begin{align}
&c_0:= \frac{ 2C_{m^y}^2(\mu \!+\! L_{l,1})}{\mu^2\gamma_y\sqrt{1\!+\!\sigma_u^2}}\! \!+\!\!\left(\frac{8\Delta_0^x}{n(1-\rho_W)}\!\!+\!\!\frac{32 \gamma_x^2 \rho_WC_{m^x}^2 (1 + \zeta_q^2)}{n\bar{q}_0^2(1 - \rho_W)^2} \right)\!\!\left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}\!\!+\!\!\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)\\
&\quad+ \frac{32 \gamma_x^2 \rho_W(1 + \zeta_q^2)}{n\bar{z}_0(1 - \rho_W)^2} \left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)+\frac{8\gamma_x^2  L_y^2\left( 1 + \zeta_q^2 \right) (\mu + L_{l,1})^2}{n\gamma_y^2\mu L_{l,1}\bar{z}_0\sqrt{1+\sigma_u^2}},\\
&d_0:= \left[\frac{32 \gamma_x^2 \rho_W(1 + \zeta_q^2)}{n(1 - \rho_W)^2} \left(\frac{(\mu+L_{l,1})^3}{\gamma_y\mu^2}+\frac{2L_{l,1}(\mu+L_{l,1})}{\gamma_y\mu}\right)+\frac{8\gamma_x^2  L_y^2\left( 1 + \zeta_q^2 \right) (\mu + L_{l,1})^2}{n\gamma_y^2\mu L_{l,1}\sqrt{1+\sigma_u^2}}\right],
\end{align}

When such $k_2$ does not exist, $\bar{m}^y_{t+1} \leq C_{m^y}$ holds for any $t < T$.

Under Assumptions 1, 2, and 3, for any positive constants $\gamma_x$, $\gamma_y$, $\gamma_v$, $m^x_{i,0}$,  $m^y_{i,0}$, and $m^v_{i,0}$, the iterates generated by alg1 satisfy:
\vspace{-0.19cm}
\begin{equation*}
\begin{aligned}
\frac{1}{T} \sum_{t=0}^{T-1} \|\nabla \Phi(\bar{x}_t)\|^2
&{\leq} \frac{2}{T}\!\Bigg[\!\!\left(\!{4}\!\left(\!\frac{\Phi(\bar{x}_0)\!-\!\Phi^*}{\gamma_x}\!\right)\!\!+\!a_7\log(T)\!\!+\!b_7\!\right)^{\!2}\!\!\!{(a_1\!\log(T) \!+\! b_1)^2}  \\
& \quad+ \!C_{m^x} \!\!\left(\!{4}\!\left(\!\frac{\Phi(\bar{x}_0)\!-\!\Phi^*}{\gamma_x}\!\right)\!\!+\!a_7\!\log(T)\!\!+\!b_7\!\right)\!(a_1\!\log(T)\!\!+\! b_1)\Bigg] \!=\! \mathcal{O}\left(\frac{\log^4(T)}{T}\right),
\end{aligned}
\end{equation*}
where $\Phi^* := \inf_{x \in \mathbb{R}^p} \Phi(x) > -\infty$, and the constants $C_{m^x}$, $a_1$, $b_1$, $a_7$, and $b_7$ are defined in Eqs.~(30), (67), and (126) in the Appendix.

Suppose 1, 2, and 3 hold. Then, no matter $k_1$ in 9 exists or not, we always have:
\begin{align}
&\Phi(\bar{x}_{t+1})\\
&\leq\Phi(\bar{x}_t)-\frac{\gamma_x \bar{q}_{t+1}^{-1}}{8}\|\nabla \Phi(\bar{x}_t)\|^2+\frac{\gamma_x\bar{q}_{t+1}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_{f}^2)}{n} \Delta_t\\
&\quad -\left(\frac{\gamma_x}{2}-{2n\gamma_x^2 L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)}\right)\frac{\|\nabla_x f(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}
+ \frac{\bar{L}^2\gamma_x }{\mu^2} \frac{\|\nabla_v r(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}  \\
&\quad +\left( \frac{\gamma_x\bar{L}^2}{2\mu^2} \!\!+\!\! \frac{\gamma_x\bar{L}^2}{\mu^4} \left( \frac{L_{l,2} C_{f_y}}{\mu} \!\!+ \!\!L_{f,1} \right)^2 \right) \frac{\|\nabla_y l(\bar{x}_t, \bar{y}_t)\|^2}{\bar{q}_{t+1}}\!+\! 2\gamma_x \bar{q}_{t+1}^{-1}  \left\| \frac{\big(\tilde{\mathbf{q}}_{t+1}^{-1}\big)^\top}{n\bar{q}_{t+1}^{-1}} \bar{\nabla} F(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) \right\|^2\!.
\end{align}
Additionally, if $k_1$ in 9 exists, we have:
\begin{align}
&\Phi(\bar{x}_{t+1})\\
&\leq\Phi(\bar{x}_t)-\frac{\gamma_x \bar{q}_{t+1}^{-1}}{8}\|\nabla \Phi(\bar{x}_t)\|^2+\frac{\gamma_x\bar{q}_{t+1}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_{f}^2)}{n} \Delta_t\\
&\quad -\frac{\gamma_x }{4}\frac{\|\nabla_x f(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}
+ \frac{\bar{L}^2\gamma_x }{\mu^2} \frac{\|\nabla_v r(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}+ 2\gamma_x \bar{q}_{t+1}^{-1}  \left\| \frac{\big(\tilde{\mathbf{q}}_{t+1}^{-1}\big)^\top}{n\bar{q}_{t+1}^{-1}} \bar{\nabla} F(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) \right\|^2\\
&\quad+\left(\! \frac{\gamma_x\bar{L}^2}{2\mu^2} + \frac{\gamma_x\bar{L}^2}{\mu^4} \!\!\left(\! \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \!\right)^2 \right)\!\! \frac{\|\nabla_y l(\bar{x}_t, \bar{y}_t)\|^2}{\bar{q}_{t+1}},
\end{align}
where $\bar{L} := \max \left\{ 2 \left( \frac{C_{f_y}^2 L_{l,2}^2}{\mu^2} + L_{f,1}^2 \right)^{\frac{1}{2}}, \, \sqrt{2} C_{l_{xy}} \right\}$.

Under 2 and 3, suppose the number of total iteration rounds in alg1 is $T$. If there exists $k_1 \leq T$ as described in 9, then we have:
\begin{equation}
\bar{m}^x_t \leq
\begin{cases}
C_{m^x}, & t \leq k_1, \\
C_{m^x} + {\left(4\left(\frac{\Phi(\bar{x}_{0})-\Phi^*}{\gamma_x}\right)+a_7\log(t+1)+b_7\right)\bar{z}_{t+1}}, & t \geq k_1,
\end{cases}
\end{equation}
where $a_7$ and $b_7$ are defined as:
\begin{align}
  a_7 &:=  \frac{4\bar{L}^2a_6 }{\mu^2\bar{m}^x_{0}}+\frac{2\bar{L}^2a_5}{\mu^2\bar{m}^x_{0}} \left( 1 + \frac{2}{\mu^2} \left( \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \right)^2 \right) \\
  &\quad+ \frac{80(1+\zeta_q^2)((1 + \rho_W) \rho_W)}{n\bar{z}_0^2\bar{q}_0(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\left[C_{l_y}^2+\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\right] \\
&\quad+\frac{4\bar{q}_{0}^{-1}(4\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_0^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n}\left(\frac{2 \Delta_0}{1 - \rho_W} 
+ \frac{40 \gamma_x^2 \rho_W (1 + \zeta_q^2)}{(1 - \rho_W)^2}\right.  \\
&\quad \left.+ \frac{8a_2 \gamma_y^2 \rho_W (1 + \zeta_u^2)}{(1 - \rho_W)^2}+\frac{8a_3 \gamma_v^2 \rho_W (1 + \zeta_z^2)}{(1 - \rho_W)^2}\right),
\end{align}
\begin{align}
b_7 &:=  \frac{4\bar{L}^2b_6}{\mu^2\bar{m}^x_{0}}+\frac{2\bar{L}^2b_5}{\mu^2\bar{m}^x_{0}} \left( 1 + \frac{2}{\mu^2} \left( \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \right)^2 \right)\\
&\quad+ \frac{16c_2(1+\zeta_q^2)((1 + \rho_W) \rho_W)}{n\bar{z}_0^2\bar{q}_0(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\left[C_{l_y}^2+\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\right] \\
&\quad+\frac{4\bar{q}_{0}^{-1}(4\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_0^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n}\left(\frac{2 \Delta_0}{1 - \rho_W} 
+ \frac{8c_2 \gamma_x^2 \rho_W (1 + \zeta_q^2)}{(1 - \rho_W)^2}\right.  \\
&\quad \left.+ \frac{8b_2 \gamma_y^2 \rho_W (1 + \zeta_u^2)}{(1 - \rho_W)^2}+\frac{8 b_3\gamma_v^2 \rho_W (1 + \zeta_z^2)}{(1 - \rho_W)^2}\right)+ \frac{8n\gamma_x C_{m^x}^2 L_\Phi \left(1 +\zeta_q^2\right)}{\bar{q}_0^2},
\end{align}
and the upper bound of $\bar{z}_t := \max\{\bar{m}^y_t, \bar{m}^v_t\}$ refers to 14. When such $k_1$ does not exist, we have $\bar{m}^x_t \leq C_{m^x}$ for any $t \leq T$.
